//! Lucide icons the default set (gpui-kit's) doesn't have, drawn from their SVG. Each is a
//! `&'static str` put together at compile time: drawing one allocates nothing, and GPUI caches
//! its raster by the bytes' hash.

use gpui_kit::component::Icon;

macro_rules! lucide {
    ($($(#[$doc:meta])* $name:ident => $paths:literal;)*) => {
        $(
            $(#[$doc])*
            #[allow(dead_code)]
            pub fn $name() -> Icon {
                const SVG: &str = concat!(
                    r#"<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">"#,
                    $paths,
                    "</svg>"
                );
                Icon::default().data(SVG.as_bytes())
            }
        )*
    };
}

